import java.util.Collection;

/*
 * The listing on the page imports java.util.Set but not java.util.HashSet.
 * Java looks for an unimported type in the current package first, so this
 * small stand-in lets the printed code compile and run unchanged: it is a
 * java.util.HashSet in every respect, just reachable without the import.
 * In your own programs, add "import java.util.HashSet;" instead and delete
 * this file.
 */
public class HashSet<E> extends java.util.HashSet<E> {
    public HashSet() {
        super();
    }

    public HashSet(Collection<? extends E> source) {
        super(source);
    }
}
